-- Iowa: the quota page became a category picker; read each deer/turkey category's live table.
UPDATE sources SET parser = 'form', check_minutes = 60, last_hash = NULL, last_error = NULL, last_checked = NULL, species = 'deer,turkey',
  parser_config = '{"field": "ctl00$ContentPlaceHolder1$ddlHuntCategoryTypes", "postback": true, "choices": [{"value": "11", "species": "deer", "label": "Nonresident any deer, zone", "defaults": {"residency": "nonresident", "sex": "either"}, "table": {"keyColumns": ["zone", "season"]}}, {"value": "10", "species": "deer", "label": "Nonresident antlerless deer,", "defaults": {"residency": "nonresident", "sex": "antlerless"}, "table": {"keyColumns": ["county name"]}}, {"value": "5", "species": "deer", "label": "Resident antlerless deer,", "defaults": {"residency": "resident", "sex": "antlerless"}, "table": {"keyColumns": ["county name"]}}, {"value": "6", "species": "deer", "label": "Resident Nov & Jan antlerless deer,", "defaults": {"residency": "resident", "sex": "antlerless"}, "table": {"keyColumns": ["county name"]}}, {"value": "7", "species": "deer", "label": "Antlerless population management, zone", "defaults": {"sex": "antlerless"}, "table": {"keyColumns": ["zone", "season", "hunt name"]}}, {"value": "4", "species": "deer", "label": "Resident early muzzleloader", "defaults": {"residency": "resident", "weapon": "muzzleloader"}, "table": {"keyColumns": ["limit"], "labelColumns": []}}, {"value": "3", "species": "turkey", "label": "Resident fall turkey, zone", "defaults": {"residency": "resident"}, "table": {"keyColumns": ["zone"]}}, {"value": "8", "species": "turkey", "label": "Nonresident spring turkey, zone", "defaults": {"residency": "nonresident"}, "table": {"keyColumns": ["zone", "season"]}}], "table": {"headerMatch": "remaining", "keyColumns": ["zone"], "quantityColumn": "remaining"}}'
  WHERE id = 'ia-quotas';
DELETE FROM listings WHERE source_id = 'ia-quotas';
